import os
import uuid
from functools import wraps

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

from taf.gnb.oam.coam.vdu.exceptions import ApiException
from taf.gnb.oam.coam.vdu.utilities.logger import log_sending_message, log_received_response
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage


def log_request_and_response(method):
    @wraps(method)
    def wrapper(self, *args, **kwargs):
        request_id = str(uuid.uuid4())
        endpoint = self.base_url + kwargs.get('endpoint')
        headers = self._construct_headers(kwargs.get('headers'))
        payload = kwargs.get('payload') or kwargs.get('data')
        json = kwargs.get('json')
        log_payload = kwargs.get('log_payload', True)
        return_response_headers = kwargs.get('return_response_headers', False)
        request_method = method.__name__.split('_')[2].upper()

        if not self.disable_logging:
            log_sending_message(request_id=request_id,
                                endpoint=endpoint,
                                payload=payload,
                                headers=headers,
                                method=request_method,
                                json=json,
                                log_payload=log_payload,
                                connection_alias=self.connection_alias)

        response = method(self, *args, **kwargs)

        if not self.disable_logging:
            log_received_response(request_id=request_id,
                                  response=response,
                                  endpoint=endpoint,
                                  method=request_method,
                                  connection_alias=self.connection_alias)

        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError:
            raise ApiException(http_response=response)

        return self._process_response(response=response,
                                      return_response_headers=return_response_headers)
    return wrapper


class HttpClient:
    """ This class provides a base for specific API clients. """

    def __init__(self, connection_alias="default"):
        self.base_url = None
        self.disable_logging = os.getenv("TAF_VDU_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
        self.connection_alias = connection_alias
        self.token_storage = TokenStorage(connection_name=self.connection_alias)

        self.session = requests.Session()

        retries = Retry(connect=5, read=5, backoff_factor=0.1)
        self.session.mount('https://', HTTPAdapter(max_retries=retries))

    @log_request_and_response
    def _send_get_request(self, endpoint, payload=None, timeout=30, headers=None, return_response_headers=False):
        """
        Make a GET request to the API and return response

        GET requests will be sent as part of the session created when initializing the client,
        this allows to implement return mechanism.

        :param endpoint: str The API endpoint to call
        :param payload: Dict(str) The request payload, defaults to None
        :param timeout: int timeout in seconds, defaults to 30
        :param headers: Dict(str) The request headers, defaults to None

        :return: API response, its type depends on the Content-Type
        :raises ApiException: If the request fails
        """
        return self.session.get(url=self.base_url + endpoint,
                                headers=self._construct_headers(headers=headers),
                                timeout=timeout,
                                verify=False,
                                params=payload)

    @log_request_and_response
    def _send_patch_request(self, endpoint, payload=None, timeout=30, headers=None):
        """
        Make a PATCH request to the API and return response

        :param endpoint: str The API endpoint to call
        :param payload: Dict(str) The request payload, defaults to None
        :param timeout: int timeout in seconds, defaults to 30
        :param headers: Dict(str) The request headers, defaults to None

        :return: API response, its type depends on the Content-Type
        :raises ApiException: If the request fails
        """
        return requests.patch(url=self.base_url + endpoint,
                              headers=self._construct_headers(headers=headers),
                              timeout=timeout,
                              verify=False,
                              json=payload)

    @log_request_and_response
    def _send_delete_request(self, endpoint, timeout=30, headers=None):
        """
        Make a DELETE request to the API and return response

        :param endpoint: str The API endpoint to call
        :param timeout: int timeout in seconds, defaults to 30
        :param headers: Dict(str) The request headers, defaults to None

        :return: API response, its type depends on the Content-Type
        :raises ApiException: If the request fails
        """
        return requests.delete(url=self.base_url + endpoint,
                               headers=self._construct_headers(headers=headers),
                               timeout=timeout,
                               verify=False)

    @log_request_and_response
    def _send_post_request(self, endpoint, data=None, json=None, timeout=30, headers=None, params=None,
                           log_payload=True):
        """
        Make a POST request to the API and return response

        :param endpoint: str The API endpoint to call
        :param data: Dict(str) The request data, defaults to None
        :param timeout: int timeout in seconds, defaults to 30
        :param headers: Dict(str) The request headers, defaults to None
        :param log_payload: bool Whether to log the payload, defaults to True

        :return: API response, its type depends on the Content-Type
        :raises ApiException: If the request fails
        """
        return requests.post(url=self.base_url + endpoint,
                             headers=self._construct_headers(headers=headers),
                             timeout=timeout,
                             verify=False,
                             data=data,
                             json=json,
                             params=params)

    @log_request_and_response
    def _send_put_request(self, endpoint, data=None, json=None, timeout=30, headers=None, params=None):
        """
        Make a PUT request to the API and return response

        :param endpoint: str The API endpoint to call
        :param data: Dict(str) The request data, defaults to None
        :param json: Dict(str) The request json data, defaults to None
        :param timeout: int timeout in seconds, defaults to 30
        :param headers: Dict(str) The request headers, defaults to None
        :param params: Dict(str) The query parameters, defaults to None

        :return: API response, its type depends on the Content-Type
        :raises ApiException: If the request fails
        """
        return requests.put(url=self.base_url + endpoint,
                            data=data,
                            json=json,
                            headers=self._construct_headers(headers=headers),
                            params=params,
                            timeout=timeout,
                            verify=False)

    @staticmethod
    def _process_response(response, return_response_headers=False):
        if (response.headers.get('Content-Type', None) == 'application/json') and (len(response.content) > 0):
            processed_content = response.json()
        else:
            processed_content = response.content

        if not return_response_headers:
            return processed_content
        else:
            return {'content': processed_content, 'headers': response.headers}


    def _construct_headers(self, headers):
        return {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            **(headers or {})
        }
